// Executable scenarios for features/record_stems.feature: the kits fitted to records hold to the
// drum stems of those records. A plain rock groove (stem_groove.hpp) is played through each
// fitted preset and measured as the song corpus measures a separated drum stem
// (stem_features.hpp); every feature must land inside the interquartile range of the records'
// drums (stem_reference.hpp, generated by tools/stem_reference.py; no audio from the records is
// in the repository).
#include <cstring>
#include <string>

#include "../src/presets.hpp"
#include "spec.hpp"
#include "stem_features.hpp"
#include "stem_groove.hpp"
#include "stem_reference.hpp"

namespace {

const stem::Reference& reference(const char* group) {
  for (const auto& r : stem::kReferences) if (std::strcmp(r.group, group) == 0) return r;
  return stem::kReferences[0];
}

bonkr::Settings preset(const char* name) {
  bonkr::Settings s = bonkr::Settings::defaults();
  for (size_t i = 0; i < bonkr::presets::count(); ++i)
    if (std::strcmp(bonkr::presets::all()[i].name, name) == 0) { bonkr::presets::apply(i, s.v.data()); return s; }
  CHECK(false, std::string("no preset named ") + name);
  return s;
}

void holds_to(const char* name, const char* group) {
  const stem::Reference& r = reference(group);
  const auto audio = stem::play(preset(name));
  const stem::Features f = stem::measure(audio.left, audio.right, stem::kRate);
  const auto inside = [](const char* what, double value, const stem::Stat& s) {
    CHECK(value >= s.q25 && value <= s.q75, spec::fmt("%.4g", value) + " " + what + spec::fmt(" outside %.4g..%.4g", s.q25, s.q75) + spec::fmt(" (records' median %.4g)", s.median));
  };
  std::printf("    %s: roll-off %.0f Hz, below 250 Hz %.2f dB, centroid %.0f Hz, crest %.2f dB, L/R correlation %.3f\n",
              name, f.rolloff85_hz, f.low_share_db, f.centroid_hz, f.crest100_db, f.corr);
  inside("roll-off Hz", f.rolloff85_hz, r.rolloff85_hz);
  inside("share below 250 Hz dB", f.low_share_db, r.low_share_db);
  inside("centroid Hz", f.centroid_hz, r.centroid_hz);
  inside("crest dB", f.crest100_db, r.crest100_db);
  inside("L/R correlation", f.corr, r.corr);
}

}  // namespace

SCENARIO(the_basement_four_track_kit_sounds_like_the_drums_of_basement_four_track_records) {
  GIVEN("the \"Four-track basement kit\" preset: a pair of microphones close on the kit in a small, damped room, onto a four-track cassette at 9.5 cm/s whose head has lost touch with the tape");
  WHEN("a plain rock groove is played on it for 30 s and measured as a separated drum stem");
  THEN("its roll-off, share below 250 Hz, centroid, crest and L/R correlation each lie inside the quartiles of the drums of 14 basement four-track records");
  holds_to("Four-track basement kit", "GBV_lofi");
}

SCENARIO(the_home_studio_psych_kit_sounds_like_the_drums_of_home_studio_psych_records) {
  GIVEN("the \"Home-studio psych kit\" preset: spot microphones and a pair in a studio-sized room, squashed, onto a worn 19 cm/s reel");
  WHEN("a plain rock groove is played on it for 30 s and measured as a separated drum stem");
  THEN("its roll-off, share below 250 Hz, centroid, crest and L/R correlation each lie inside the quartiles of the drums of 12 home-studio psych records");
  holds_to("Home-studio psych kit", "OTC");
}

SCENARIO(the_taped_psych_rock_kit_is_thinner_than_either) {
  GIVEN("the \"Psych rock kit, taped\" preset, fitted to studio psych records rather than these");
  WHEN("the same groove is played on it");
  const auto audio = stem::play(preset("Psych rock kit, taped"));
  const stem::Features f = stem::measure(audio.left, audio.right, stem::kRate);
  THEN("its share below 250 Hz lies under both groups' quartiles: the gate tells the kits apart");
  CHECK(f.low_share_db < reference("GBV_lofi").low_share_db.q25 && f.low_share_db < reference("OTC").low_share_db.q25, spec::fmt("below 250 Hz %.2f dB", f.low_share_db));
}

int main(int argc, char** argv) { return spec::run(argc, argv); }
